insert into public.items (id, block, demand, options, explain, seq, steps) values ('m6-jumble-01', 'M6', 0, '[]'::jsonb, 'An opening greets the audience, states the motion and your side, then previews your points in order.', array[1, 3, 0, 2]::int[], '["An opening starts by greeting the audience.","Next, state the motion and which side your team is on.","Then preview your points in order, starting with the first.","The preview ends with your last point."]'::jsonb);
insert into public.items (id, block, demand, options, explain, seq, steps) values ('m6-jumble-02', 'M6', 1, '[]'::jsonb, 'A closing signals the end, sums up your best points, answers their strongest point, and finishes with why you should win.', array[3, 0, 2, 1]::int[], '["A closing starts by signalling the end (''To conclude…'').","Then sum up your best points. No new points in a closing.","Next, answer the other side''s strongest point.","Finish strongly: tell the audience why your side should win."]'::jsonb);
insert into public.items (id, block, demand, options, explain, seq, steps) values ('m6-jumble-03', 'M6', 2, '[]'::jsonb, 'Even the Opposition opens the same way: greet, say the motion and your side, then preview your points in order.', array[2, 3, 0, 1]::int[], '["An opening starts by greeting the audience.","Next, state the motion and which side your team is on.","Then preview your points in order, starting with the first.","The preview ends with your last point."]'::jsonb);
